            Java

    import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Trie {

    public class TrieNode {
        Map<Character, TrieNode> children;
        char c;
        boolean isWord;

        public TrieNode(char c) {
            this.c = c;
            children = new HashMap<>();
        }

        public TrieNode() {
            children = new HashMap<>();
        }

        public void insert(String word) {
            if (word == null || word.isEmpty())
                return;
            char firstChar = word.charAt(0);
            TrieNode child = children.get(firstChar);
            if (child == null) {
                child = new TrieNode(firstChar);
                children.put(firstChar, child);
            }

            if (word.length() > 1)
                child.insert(word.substring(1));
            else
                child.isWord = true;
        }

    }

    TrieNode root;

    public Trie(List<String> words) {
        root = new TrieNode();
        for (String word : words)
            root.insert(word);

    }

    public boolean find(String prefix, boolean exact) {
        TrieNode lastNode = root;
        for (char c : prefix.toCharArray()) {
            lastNode = lastNode.children.get(c);
            if (lastNode == null)
                return false;
        }
        return !exact || lastNode.isWord;
    }

    public boolean find(String prefix) {
        return find(prefix, false);
    }

    public void suggestHelper(TrieNode root, List<String> list, StringBuffer curr) {
        if (root.isWord) {
            list.add(curr.toString());
        }

        if (root.children == null || root.children.isEmpty())
            return;

        for (TrieNode child : root.children.values()) {
            suggestHelper(child, list, curr.append(child.c));
            curr.setLength(curr.length() - 1);
        }
    }

    public List<String> suggest(String prefix) {
        List<String> list = new ArrayList<>();
        TrieNode lastNode = root;
        StringBuffer curr = new StringBuffer();
        for (char c : prefix.toCharArray()) {
            lastNode = lastNode.children.get(c);
            if (lastNode == null)
                return list;
            curr.append(c);
        }
        suggestHelper(lastNode, list, curr);
        return list;
    }


    public static void main(String[] args) {
        List<String> words = List.of("hello", "dog", "hell", "cat", "a", "hel","help","helps","helping");
        Trie trie = new Trie(words);

        System.out.println(trie.suggest("hel"));
    }

}


            C#

    // C# program to demonstrate auto-complete feature
// using Trie data structure.
using System;
using System.Collections.Generic;

// trie node
class TrieNode {
    public TrieNode[] children = new TrieNode[26];
    // isWordEnd is true if the node represents
    // end of a word
    public bool isWordEnd = false;
}

class Trie {
    TrieNode root;
    public Trie() {
        root = new TrieNode();
    }

    // If not present, inserts key into trie.  If the
    // key is prefix of trie node, just marks leaf node
    public void Insert(string key) {
        TrieNode pCrawl = root;
        for (int i = 0; i < key.Length; i++) {
            int index = key[i] - 'a';
            if (pCrawl.children[index] == null) {
                pCrawl.children[index] = new TrieNode();
            }
            pCrawl = pCrawl.children[index];
        }
        // mark last node as leaf
        pCrawl.isWordEnd = true;
    }

    // Returns 0 if current node has a child
    // If all children are NULL, return 1.
    bool IsLastNode(TrieNode root) {
        for (int i = 0; i < 26; i++) {
            if (root.children[i] != null) {
                return false;
            }
        }
        return true;
    }

    // Recursive function to print auto-suggestions for given
    // node.
    void suggestionsRec(TrieNode root, string currPrefix) {
        // found a string in Trie with the given prefix
        if (root.isWordEnd) {
            Console.WriteLine(currPrefix);
        }
        for (int i = 0; i < 26; i++) {
            if (root.children[i] != null) {
                // child node character value
                char c = (char)(i + 'a');
                suggestionsRec(root.children[i], currPrefix + c);
            }
        }
    }

    // print suggestions for given query prefix.
    public int printAutoSuggestions(string query) {
        TrieNode pCrawl = root;
        for (int i = 0; i < query.Length; i++) {
            int index = query[i] - 'a';
            // no string in the Trie has this prefix
            if (pCrawl.children[index] == null) {
                return 0;
            }
            pCrawl = pCrawl.children[index];
        }
        // If prefix is present as a word, but
        // there is no subtree below the last
        // matching node.
        if (IsLastNode(pCrawl)) {
            Console.WriteLine(query);
            return -1;
        }
        suggestionsRec(pCrawl, query);
        return 1;
    }
}

// Driver Code
class Program {
    static void Main(string[] args) {
        Trie trie = new Trie();
        trie.Insert("hello");
        trie.Insert("dog");
        trie.Insert("hell");
        trie.Insert("cat");
        trie.Insert("a");
        trie.Insert("hel");
        trie.Insert("help");
        trie.Insert("helps");
        trie.Insert("helping");
        int comp = trie.printAutoSuggestions("hel");

        if (comp == -1) {
            Console.WriteLine("No other strings found with this prefix");
        }
        else if (comp == 0) {
            Console.WriteLine("No string found with this prefix");
        }
    }
}

